INSERT INTO products (id, category_id, name, brand, description, price, quantity, views, sales, deleted_at, created_at, updated_at) VALUES
(1, 12, '[각인/선물포장] 퓨어 컬러 젤리 글로우 밤(+거울 증정)', '에스티로더', '이 상품은 에스티로더의 퓨어 컬러 젤리 글로우 밤이며, 립밤 유형입니다. 용량·수량: 3g. 주요 사양: 모든 피부타입 (01 언어폴로제티컬리 미, 02 벨 마카롱, 03 남산 선셋, 04 누드 센세이션, 05 퓨어 로즈, 06 핑크 칠, 07 라일락 참, 08 라벤더 판타지, 09 서브틀 멀베리, 10 코랄 바이탈리티, 11 로즈 블리스, 12 루비 참, 13 럭키 페리도트). 사용 방법: 입술이 건조할 때 수시로 발라줍니다. 립스틱 사용 전 립 밤을 함께 사용하면 보습감과 편안함은 물론, 한층 더 선명한 컬러감을 연출 할 수 있습니다.', 39000, 100, 47752, 2958, NULL, '2026-07-13 19:49:17.000000', '2026-09-17 02:58:46.000000'),
(2, 28, '뉴트리포유 듀얼+ 이뮨 종합 멀티비타민&미네랄 7입+2입 증정 - 선물하기 단독 에디션', '뉴트리포유', '이 상품은 뉴트리포유의 듀얼+ 이뮨 종합 멀티비타민&미네랄 7입이며, 비타민 유형입니다.', 19900, 100, 604, 523, NULL, '2025-03-21 11:21:23.000000', '2026-04-18 14:15:04.000000'),
(3, 26, '홈카페 브런치 요거트볼 5종세트 (그릭요거트+그래놀라+허니스틱)', '룩트', '이 상품은 룩트의 홈카페 브런치 요거트볼 5종세트 (그릭요거트+그래놀라+허니스틱)이며, 떠먹는요거트/그릭요거트 유형입니다. 식품 유형: 농후발효유(요거트) / 기타가공품 및 곡류가공품 (그래놀라 5종) / 벌꿀(허니스틱).', 29900, 100, 42366, 4254, NULL, '2025-02-28 14:31:48.000000', '2026-05-03 14:57:18.000000'),
(4, 29, '전남 영암 프리미엄 홍무화과 1kg이상(500g*2팩)', '온브릭스', '이 상품은 온브릭스의 전남 영암 프리미엄 홍무화과 1kg이상(500g*2팩)이며, 기타 과일 유형입니다. 용량·수량: 농산물 특성상.', 22900, 100, 48051, 4958, NULL, '2025-01-31 03:52:43.000000', '2025-03-22 21:09:50.000000'),
(5, 49, '풀리오 종아리마사지기 V3+카카오파우치+카카오쇼핑백M 증정', '풀리오', '이 상품은 풀리오의 종아리마사지기 V3+카카오파우치이며, 발/다리 마사지기 유형입니다. 크기·치수: 638*350*43mm.', 150000, 100, 27275, 494, NULL, '2025-12-23 04:08:37.000000', '2026-09-09 10:26:39.000000'),
(6, 12, '[각인/선물포장] 프라다 립 밤 (+패러독스 1.2ml)', '프라다(뷰티)', '이 상품은 프라다(뷰티)의 립 밤 (+패러독스 1.2ml)이며, 립밤 유형입니다. 용량·수량: 3.8g. 주요 사양: 모든 피부용. 사용 방법: "입술 쪽에 트라이앵글 쉐입 부분을 대고 바르세요. 아이코닉한 트라이앵글 불릿이 입술 윤곽을 따라 발라지며 하루 종일 편안함을 선사합니다.".', 60000, 100, 10074, 4373, NULL, '2026-02-05 03:23:26.000000', '2026-04-30 01:20:59.000000'),
(7, 12, '[각인/선물포장] 프라다 모노크롬 립스틱', '프라다(뷰티)', '이 상품은 프라다(뷰티)의 모노크롬 립스틱이며, 립스틱 유형입니다. 용량·수량: 3.8g. 주요 사양: 모든 피부용. 사용 방법: "입술 쪽에 트라이앵글 쉐입 부분을 대고 바르세요. 아이코닉한 트라이앵글 불릿이 입술 윤곽을 또렷하게 살려주어 정교한 립 메이크업을 완성해 줍니다. ".', 68000, 100, 35501, 1677, NULL, '2026-02-10 04:44:34.000000', '2026-03-24 03:33:18.000000'),
(8, 20, '[온라인 단독] 티파니 T 스마일 스몰 펜던트 (18K 로즈 골드)', '티파니앤코', '이 상품은 티파니앤코의 티파니 T 스마일 스몰 펜던트 (18K 로즈 골드)이며, 골드 목걸이 유형입니다.', 2380000, 100, 19091, 2101, NULL, '2025-10-28 10:50:16.000000', '2026-01-03 04:22:24.000000'),
(9, 30, '농협안심한우 1++등급 ''감동'' 한우 구이세트 400g (갈비살200g+살치살200g)', '농협안심한우', '이 상품은 농협안심한우의 1++등급 ''감동'' 한우 구이세트 400g (갈비살200g+살치살200g)이며, 한우 선물세트 유형입니다.', 57500, 100, 25721, 3011, NULL, '2025-08-30 10:55:32.000000', '2025-10-08 18:25:32.000000'),
(10, 47, '스위프클링 유선 이불 침구청소기 오아 진드기 쇼파 침대 카페트 매트리스 러그 집먼지 UV살균 청소기 집들이선물', '보아르', '이 상품은 보아르의 스위프클링 유선 이불 침구청소기 오아 진드기 쇼파 침대 카페트 매트리스 러그 집먼지 UV살균 청소기 집들이선물이며, 침구청소기 유형입니다.', 44900, 100, 7895, 3369, NULL, '2025-02-19 14:44:18.000000', '2025-05-19 19:56:49.000000'),
(11, 58, '[백일선물/돌 선물] 국민 이유식 턱받이&이유식기(디너세트)', '베이비뵨', '이 상품은 베이비뵨의 국민 이유식 턱받이&이유식기(디너세트)이며, 이유식기 유형입니다. 구성: 그릇1, 스푼1, 포크1, 컵1, 턱받이1. 소재: 턱받이: PP, TPE 식기: ABS (안쪽 접시), PP+TPE (바깥 접시) 스푼, 포크,컵: TPE (손잡이), PP (스푼, 포크).', 54900, 100, 13577, 1993, NULL, '2025-08-31 04:18:01.000000', '2026-03-12 07:20:49.000000'),
(12, 24, '파인 플레이버 커피 드립백 (12개입) 16종 택1', 'BACHA COFFEE(바샤커피)', '이 상품은 BACHA COFFEE(바샤커피)의 파인 플레이버 커피 드립백 (12개입) 16종 택1이며, 믹스/인스턴트커피 유형입니다. 용량·수량: 144g (12gX12bags).', 40740, 100, 18430, 144, NULL, '2025-02-24 00:16:09.000000', '2025-10-25 02:38:26.000000'),
(13, 12, '"각인거울키링" 립글로이밤 &립펜슬 증정 &하트 경첩 키링 (선물포장)', '아떼', '이 상품은 아떼의 립글로이밤이며, 립밤 유형입니다. 용량·수량: 3.3G. 주요 사양: 모든 피부용. 사용 방법: 입술선을 따라 부드럽게 펴 발라 줍니다.', 24900, 100, 46630, 4923, NULL, '2025-05-22 07:22:14.000000', '2025-09-20 12:45:08.000000'),
(14, 30, '농협안심한우 1++등급 "투뿔 1.2kg 프리미엄 특선" 한우세트(등심500g+안심200g+채끝300g+갈비살200g)', '농협안심한우', '이 상품은 농협안심한우의 1++등급 "투뿔 1.2kg 프리미엄 특선" 한우세트(등심500g+안심200g+채끝300g+갈비살200g)이며, 한우 선물세트 유형입니다.', 159800, 100, 1475, 367, NULL, '2026-08-24 02:51:11.000000', '2026-09-19 00:41:52.000000'),
(15, 36, '[새차선물/첫차선물] "상쾌한 향기가 솔솔" 톰과 제리X카카오프렌즈 차량방향제_라이언&춘식이', '프렌즈리빙', '이 상품은 프렌즈리빙의 톰과 제리X카카오프렌즈 차량방향제_라이언&춘식이이며, 차량용 방향제 유형입니다. 용량·수량: 라이언: 5.2*6.4*3.9cm 춘식이: 4.6*5*2.9cm / 2ml. 용도·형태: 비분사형-보충형(액체형) / 자동차용-실내용.', 22000, 100, 41119, 1260, NULL, '2025-04-16 11:03:26.000000', '2025-06-02 12:53:50.000000'),
(16, 12, '[각인+포장] NEW 잉크 틴트 블러/바이닐', '입생로랑', '이 상품은 입생로랑의 잉크 틴트 블러/바이닐이며, 립틴트 유형입니다. 용량·수량: 5.5ml. 주요 사양: 모든 피부용. 사용 방법: 내장된 팁을 사용하여 입술에 자연스럽게 발라줍니다.', 55000, 100, 37864, 1672, NULL, '2025-04-23 05:00:07.000000', '2025-09-21 03:40:33.000000'),
(17, 13, '[단독구성] 톰 포드 아이코닉 향수 디스커버리 듀오 4MLx2', '톰 포드(뷰티)', '이 상품은 톰 포드(뷰티)의 아이코닉 향수 디스커버리 듀오 4MLx2이며, 공용향수 유형입니다. 용량·수량: 4ML*2. 주요 사양: 모든 피부용. 사용 방법: 마개를 이용해 적정량을 맥박이 뛰는 곳에 가볍게 발라줍니다.', 69000, 100, 41922, 2160, NULL, '2025-01-18 20:56:19.000000', '2026-07-30 21:46:04.000000'),
(18, 49, '물리치료사도 매일 사용하는 손목 힐링템ㅣTENS+EMS 마사지 저주파 무선 얼라인랩 릴렉스 손목 마사지기 육아 직장인 선물', '얼라인랩', '이 상품은 얼라인랩의 물리치료사도 매일 사용하는 손목 힐링템ㅣTENS+EMS 마사지 저주파 무선 얼라인랩 릴렉스 손목 마사지기 육아 직장인 선물이며, 안마기 유형입니다. 크기·치수: 스트랩360x85x6.5mm / 메인 기기 50x54x22.5mm.', 34900, 100, 31150, 2873, NULL, '2025-03-17 22:44:27.000000', '2026-05-17 03:51:16.000000'),
(19, 28, '옵티젠 이뮨 멀티비타민&미네랄 / 옵티젠 리프레쉬 마그네슘&징코플러스/ 바이탈 밀크씨슬&비타민(7입) 택1', '옵티젠', '이 상품은 옵티젠의 이뮨 멀티비타민&미네랄 / 옵티젠 리프레쉬 마그네슘&징코플러스/ 바이탈 밀크씨슬&비타민(7입) 택1이며, 비타민 유형입니다.', 19900, 100, 3469, 1366, NULL, '2025-09-30 00:59:30.000000', '2025-11-02 16:51:56.000000'),
(20, 28, '뉴트리포유 듀얼+ 이뮨 종합 멀티비타민&미네랄 30입+2입 증정 - 선물하기 단독 기획팩', '뉴트리포유', '이 상품은 뉴트리포유의 듀얼+ 이뮨 종합 멀티비타민&미네랄 30입이며, 비타민 유형입니다.', 56900, 100, 22362, 2121, NULL, '2026-05-10 23:52:37.000000', '2026-08-21 03:57:00.000000'),
